#!/usr/bin/env bash
# Evidence: the session-repo hint learns from WORK, not from incidental READS.
#
# GENERATED BY THIS SCRIPT — it writes its own transcript via `exec >"$OUT"`, so
# `generated-by` is a fact about the file rather than a claim about who typed it.
# Re-run to reproduce:
#
#   bash docs/evidence/session-repo-hint-provenance-2026-10-22.sh
#
# READ-ONLY: the probe imports the enforcer and repoints its GOVERNANCE_STATE_DIR at a
# throwaway directory, so it cannot read or write live governance state.
set -uo pipefail

REPO="${REPO:-$HOME/hermes-cortex}"
DEPLOYED="${DEPLOYED:-$HOME/.hermes/plugins/governance-enforcer/__init__.py}"
PREFIX_REV="${PREFIX_REV:-17f4fb8e}"   # the revision immediately BEFORE this fix
OUT="${OUT:-$REPO/docs/evidence/session-repo-hint-provenance-2026-10-22.txt}"
exec >"$OUT" 2>&1

norm() { sed -e "s|$HOME|~|g"; }
say()  { printf '%s\n' "$*"; }
rule() { printf '%s\n' "────────────────────────────────────────────────────────────"; }

say "session-repo hint provenance — evidence"
say "captured-at : $(cd "$REPO" && git rev-parse --short HEAD)  (the working tree's revision)"
say "generated-by: docs/evidence/session-repo-hint-provenance-2026-10-22.sh (this file wrote itself)"
say "pre-fix base: $PREFIX_REV  (PINNED, immutable — the revision immediately before the fix)"
say "              extracted with 'git show', NOT read from the live deployed copy, so the"
say "              comparison stays discriminating and reproducible at ANY time."
say "deployed    : ~/.hermes/plugins/governance-enforcer/__init__.py (the copy in force now)"
rule

say ""
say "1. The defect — the ROOT CAUSE of a lock scoped to the wrong repository"
say "   _note_session_repo (governance-enforcer) is documented as recording 'the repo this"
say "   session was last seen USING'. It learned it from the PATH ARGUMENTS of every tool"
say "   call, consulting"
say ""
say "       _PATH_ARG_KEYS = (\"path\", \"file_path\", \"workdir\", \"cwd\", \"directory\")"
say ""
say "   and RETURNING ON THE FIRST KEY PRESENT. So a bare file 'path' outranked an explicit"
say "   'workdir', and ANY call whose path argument landed in another repo re-homed the"
say "   session — including a pure READ. Measured on this host 2026-10-22: a single"
say "   search_files(path=<another repo>), made while surveying that repo, re-homed this"
say "   session. begin_change's _derive_repo_path then resolved source 0 to that repo, the"
say "   lock was recorded against it, the review scope judged ITS blobs, and (before"
say "   eb9a5edf) that lock authorised writes in ANY repo."
say ""
say "   Reading a file is not evidence of WORKING in a repository."
rule

say ""
say "2. The both-ways tests (tests/test_loop_gov_review_repo.py)"
say "   \$ ~/.hermes-cortex/venv/bin/python3 -m pytest tests/test_loop_gov_review_repo.py -q"
~/.hermes-cortex/venv/bin/python3 -m pytest "$REPO/tests/test_loop_gov_review_repo.py" -q 2>&1 | norm | tail -3
~/.hermes-cortex/venv/bin/python3 -m pytest "$REPO/tests/test_loop_gov_review_repo.py" -q >/dev/null 2>&1
say "   rc=$?   (0 = all pass, including the three new provenance tests and the 13 existing"
say "          ones — the new tool_name argument is optional, so every existing caller works)"
rule

say ""
say "3. DIFFERENTIAL PROBE (enforcement-change-safety Rule 23)"
say "   Three copies loaded in ONE process, driven with the SAME inputs against a throwaway"
say "   state dir (never live governance state):"
say "     pre-fix  = the pinned revision via 'git show' — the behaviour being replaced"
say "     deployed = the copy in force right now        — proves the deploy landed"
say "     repo     = the working tree                   — the fix under test"
say "   Each case starts with the session's hint ALREADY SET to 'proj' (except the"
say "   first-touch case), which is the situation that matters: the session knows its repo."
say "   The pre-fix copy has no tool_name argument, so the probe calls it with its own"
say "   2-argument signature — that IS the pre-fix behaviour, not a probe artefact."
say ""
~/.hermes-cortex/venv/bin/python3 - "$REPO" "$PREFIX_REV" "$DEPLOYED" "$REPO/plugins/governance-enforcer/__init__.py" <<'PROBE' 2>&1 | norm
import importlib.util, subprocess, sys, tempfile
from pathlib import Path

REPO, PREFIX_REV, DEPLOYED, REPOCOPY = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]


def load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def git_repo(parent, name):
    repo = parent / name
    repo.mkdir()
    subprocess.run(["git", "init", "-q", str(repo)], check=True, capture_output=True)
    return repo


def call_learn(mod, sid, args, tool_name):
    """Call _note_session_repo as THIS copy allows — pre-fix has no tool_name."""
    try:
        mod._note_session_repo(sid, args, tool_name=tool_name)
    except TypeError:
        mod._note_session_repo(sid, args)


tmp = Path(tempfile.mkdtemp(prefix="hint-provenance."))
proj = git_repo(tmp, "proj")
other = git_repo(tmp, "other")
state = tmp / "state"
state.mkdir()

# (label, start-hint (None = no hint yet), tool_name, args, expect_the_verdict_to_change)
CASES = [
    ("read of another repo (the bug)",
     "proj", "search_files", {"path": str(other / "f.txt")}, True),
    ("write in another repo (real work)",
     "proj", "write_file", {"file_path": str(other / "f.txt")}, False),
    ("explicit workdir in another repo",
     "proj", "terminal", {"workdir": str(other)}, False),
    ("workdir outranks a file path (ORDER)",
     "proj", "terminal", {"path": str(other / "f.txt"), "workdir": str(proj)}, True),
    ("first touch, hint empty, read",
     None, "search_files", {"path": str(other / "f.txt")}, False),
]

prefix = tmp / "enforcer-before-the-fix.py"
prefix.write_bytes(subprocess.run(
    ["git", "-C", REPO, "show", f"{PREFIX_REV}:plugins/governance-enforcer/__init__.py"],
    check=True, capture_output=True).stdout)

COPIES = [("pre-fix", prefix), ("deployed", Path(DEPLOYED)), ("repo", Path(REPOCOPY))]
print(f"  {'case':38} {'pre-fix':>10} {'deployed':>9} {'repo':>8}   verdict")
print(f"  {'-'*38} {'-'*10} {'-'*9} {'-'*8}   -------")
ok = True
deploy_agrees = True
for label, start_hint, tool_name, args, expect_change in CASES:
    got = {}
    for name, path in COPIES:
        mod = load(f"probe_{name}", path)
        mod.GOVERNANCE_STATE_DIR = state
        hint = state / "session-repo" / "S-probe"
        hint.parent.mkdir(parents=True, exist_ok=True)
        if start_hint is None:
            hint.unlink(missing_ok=True)
        else:
            hint.write_text(str(tmp / start_hint))
        call_learn(mod, "S-probe", dict(args), tool_name)
        got[name] = mod._session_repo_slug("S-probe")
    did_change = got["pre-fix"] != got["repo"]
    notes = ["CHANGED (the fix)" if did_change else "identical"]
    if got["deployed"] != got["repo"]:
        notes.append("DEPLOY MISMATCH")
        deploy_agrees = False
    print(f"  {label:38} {got['pre-fix']:>10} {got['deployed']:>9} {got['repo']:>8}   "
          f"{' · '.join(notes)}")
    if did_change != expect_change:
        ok = False

print()
if ok and deploy_agrees:
    print("  OK: the verdict changed ONLY where the defect was — a READ of another repo no")
    print("      longer re-homes a session, while a WRITE there, an explicit workdir, and")
    print("      first-touch learning are all unchanged. Deployed agrees with repo on every")
    print("      row, so the fix is live.")
else:
    print(f"  FAIL: pattern matches={ok} deploy_agrees={deploy_agrees} — inspect the rows above.")
sys.exit(0 if (ok and deploy_agrees) else 1)
PROBE
probe_rc=${PIPESTATUS[0]}
say "   rc=$probe_rc   (0 = changed exactly where the defect was, and live)"
rule

say ""
say "4. Syntax + the A4 adversarial gate"
python3 -m py_compile "$REPO/plugins/governance-enforcer/__init__.py"
say "   plugins/governance-enforcer/__init__.py py_compile_rc=$?"
python3 "$HOME/.hermes-cortex/scripts/adversarial-verify.py" \
    --file "$REPO/plugins/governance-enforcer/__init__.py" --level A4 --gate >/dev/null 2>&1
say "   plugins/governance-enforcer/__init__.py A4_rc=$?"
rule

say ""
say "5. What the fix does"
say "   • An EXPLICIT working directory (workdir/cwd) is consulted FIRST. It states where the"
say "     session IS; a bare file 'path' only says what it looked at. 'path' used to be"
say "     consulted first, so the weakest signal always won."
say "   • A bare file/dir path counts only as evidence of WORK: the call must be write-class"
say "     (_is_write_tool — this module's canonical fail-closed classifier, whose READ_TOOLS"
say "     set already lists read_file and search_files), or the session must not know its repo"
say "     yet, which leaves first-touch learning from any path exactly as it was."
say "   • The new tool_name argument is optional, so all three existing callers in"
say "     tests/test_loop_gov_review_repo.py keep working unchanged."
rule

say ""
say "6. CORRECTION of a claim I made in the PREVIOUS cycle, carried here so the record is right"
say "   commit eb9a5edf's message, and the matching governed note, state that 'no writer for"
say "   [the hint] exists in either repo'. That is FALSE. The writer is _note_session_repo in"
say "   plugins/governance-enforcer/__init__.py. I had grepped for the hint FILENAME"
say "   (_session_repo_hint_path), which appears only at its def and two read sites, and"
say "   wrongly concluded from that absence that nothing wrote it. The correct method — find"
say "   the thing that WRITES the path, not the callers of the path's constructor — is what"
say "   located the actual writer, and it is what this cycle fixes."
rule

say ""
say "7. What this capture covers"
say "   UNCOMMITTED at capture time only for the .txt itself; the code and test are committed."
say "   HEAD at capture: $(cd "$REPO" && git rev-parse --short HEAD)"
(cd "$REPO" && git status --short -- plugins/governance-enforcer/__init__.py tests/test_loop_gov_review_repo.py docs/evidence/session-repo-hint-provenance-2026-10-22.sh docs/evidence/session-repo-hint-provenance-2026-10-22.txt | norm | sed 's/^/     /')
rule
say ""
say "end of evidence"
